              const vehiclePhotos = {
                front: fileMeta('photoFront'),
                rear: fileMeta('photoRear'),
                left: fileMeta('photoLeft'),
                right: fileMeta('photoRight'),
                extra: fileMetaFromSelector('.vehicleExtraPhoto')
              };
